def sum_nested_list(nested_list):
    """
    Recursively calculates the sum of all numbers in a nested list.

    Args:
        nested_list: A list that may contain numbers and other lists.

    Returns:
        The sum of all numbers in the nested list (float if any float is present, 
        otherwise int).
    """
    total_sum = 0.0  # Initialize as float to handle floating-point numbers
    for element in nested_list:
        if isinstance(element, (int, float)):
            total_sum += element
        elif isinstance(element, list):
            total_sum += sum_nested_list(element)
    return total_sum

if __name__ == "__main__":
    input_str = input()
    try:
        nested_list = eval(input_str)  # Evaluate the input string as a Python list
        if isinstance(nested_list, list):
            result = sum_nested_list(nested_list)
            print(result)
        else:
            print("Invalid input: Input must be a list.")
    except (SyntaxError, NameError, TypeError):
        print("Invalid input: Please provide a valid Python list expression.")
