def main():
    library = {}

    while True:
        command = input().split()

        if not command:
            continue

        action = command[0].upper()

        if action == "ADD":
            title = command[1]
            quantity = int(command[2])
            if title in library:
                library[title] += quantity
                print(f"Added {quantity} copy(s) of '{title}'")
            else:
                library[title] = quantity
                print(f"Added {quantity} copy(s) of '{title}'")

        elif action == "CHECKOUT":
            title = command[1]
            if title in library and library[title] > 0:
                library[title] -= 1
                print(f"Checked out '{title}'")
            else:
                print(f"'{title}' is not available for checkout")

        elif action == "RETURN":
            title = command[1]
            if title in library:
                library[title] += 1
                print(f"Returned '{title}'")
            else:
                print(f"Cannot return '{title}', it's not part of this library")

        elif action == "LIST":
            if not library:
                print("There are no books available in the library")
            else:
                sorted_books = sorted(library.items())
                print("Available books:")
                for title, quantity in sorted_books:
                    print(f"- {title}: {quantity} copy(s)")

        elif action == "EXIT":
            break

        else:
            print("Invalid command.")

if __name__ == "__main__":
    main()
