import xml.etree.ElementTree as ET

def xml_to_dict(xml_string):
    """
    Converts an XML string to a nested dictionary.

    Args:
        xml_string: The XML string to convert.

    Returns:
        A nested dictionary representing the XML.
    """

    root = ET.fromstring(xml_string)

    def element_to_dict(element):
        d = {}

        # Add attributes
        for key, value in element.attrib.items():
            d['@' + key] = value

        # Add text content
        if element.text:
            d['#text'] = element.text.strip()

        # Add child elements
        children = {}
        for child in element:
            child_dict = element_to_dict(child)
            if child.tag in children:
                if isinstance(children[child.tag], list):
                    children[child.tag].append(child_dict)
                else:
                    children[child.tag] = [children[child.tag], child_dict]
            else:
                children[child.tag] = child_dict

        if children:
            d.update(children)

        return d

    return element_to_dict(root)

if __name__ == "__main__":
    xml_string = input()
    result_dict = xml_to_dict(xml_string)
    print(result_dict)
