class Node:
    def __init__(self, data):
        self.data = data
        self.next = None
        self.prev = None

class Stack:
    def __init__(self):
        self.head = None

    def push(self, x):
        new_node = Node(x)
        new_node.next = self.head
        if self.head:
            self.head.prev = new_node
        self.head = new_node

    def pop(self):
        if self.is_empty():
            print("Stack Underflow")
            return

        print(self.head.data)
        self.head = self.head.next
        if self.head:
            self.head.prev = None

    def peek(self):
        if self.is_empty():
            print("Stack Underflow")
            return

        print(self.head.data)

    def is_empty(self):
        if self.head is None:
            print("True")
        else:
            print("False")

if __name__ == "__main__":
    n = int(input())
    stack = Stack()
    for _ in range(n):
        operation = input().split()
        if operation[0] == 'push':
            stack.push(int(operation[1]))
        elif operation[0] == 'pop':
            stack.pop()
        elif operation[0] == 'peek':
            stack.peek()
        elif operation[0] == 'is_empty':
