import json

def convert_keys_to_uppercase(data):
  """
  Recursively converts all dictionary keys in a JSON-like data structure to uppercase.

  Args:
    data: A dictionary, list, or other JSON-compatible data type.

  Returns:
    A new data structure with dictionary keys converted to uppercase.
  """
  if isinstance(data, dict):
    return {key.upper(): convert_keys_to_uppercase(value) for key, value in data.items()}
  elif isinstance(data, list):
    return [convert_keys_to_uppercase(item) for item in data]
  else:
    return data

