        command = input()
        parts = command.split()

        if parts[0] == "deposit":
            try:
                amount = float(parts[1])
                if amount > 0:
                    balance += amount
                    transaction_log.append(f"Deposited: {amount}")
                    print(f"Deposited: {amount}")
                else:
