            except (IndexError, ValueError):
                print("Invalid amount")

        elif parts[0] == "withdraw":
            try:
                amount = float(parts[1])
                if amount > 0:
                    if balance >= amount:
                        balance -= amount
                        transaction_log.append(f"Withdrew: {amount}")
                        print(f"Withdrew: {amount}")
                    else:
                        print("Insufficient funds")
                else:
                    print("Invalid amount")
            except (IndexError, ValueError):
                print("Invalid amount")

        elif parts[0] == "balance":
            print(balance)

        elif parts[0] == "log":
            for entry in transaction_log:
                print(entry)

        elif parts[0] == "exit":
            break

        else:
            print("Invalid command")

if __name__ == "__main__":
    banking_system()
